// One-bit wide PARITY function: computes the parity of one byte (9 total bits,
// counting the parity bit itself).
function [0:0] PARITY;
    input [7:0] D;
    reg        P;
    integer    i;
    begin
        P = 1'b0;
        for (i = 0; i < 8; i = i + 1)
            P = P ^ D[i];
        PARITY = P;
    end
endfunction

// Top-level module: computes parity of the input byte.
module TopModule (
    input  [7:0] in,
    output reg   parity
);
    always @(*) parity = PARITY(in);
endmodule

